//! A service definition written in Java — DDS-RPC 1.0 §7.3.2.
//!
//! §7.3.2 is not a code-generation clause. It says a *service
//! definition* may be written in Java rather than in IDL, and fixes the
//! syntax: "Conforming implementations shall support the syntax
//! generated by the following modified productions from the Java
//! grammar" — nine productions, cut down from Java SE 5 so that an
//! interface declares only methods and a class declares only data
//! members. The directions come from annotations: "In, out, and inout
//! parameters are specified using the `@in`, `@out` and `@inout`
//! annotations. By default the parameters are read only, and the use of
//! `@in` is optional. One or more operations may be marked oneway using
//! the `@oneway` annotation."
//!
//! So this is a reader for that subset. What comes out is
//! [`JavaServiceDef`], which carries the same name, the same methods and
//! the same checks as the [`crate::service_mapping::ServiceDef`] an IDL
//! interface lowers to — [`JavaInterface::service_def`] runs the
//! `oneway`, duplicate-method and duplicate-parameter checks
//! `lower_service` runs — and one thing it cannot carry: a Java source
//! names its types and has no model behind them, so [`JavaMethod`]'s
//! types are names rather than handles. Resolving a name to a
//! [`zerodds_ast::TypeNode`] is a question about which model the
//! definition is read against, and the reader does not invent an
//! answer.
//!
//! ## What it refuses
//!
//! Everything the modified productions removed, by name: generic type
//! parameters (`NormalInterfaceDeclaration`, `NormalClassDeclaration`),
//! annotation type declarations (`InterfaceDeclaration`), static
//! initialiser blocks (`ClassBodyDeclaration`), constructors and methods
//! in a class body (`MemberDecl`, `MethodOrFieldRest`). A reader that
//! skipped them would accept a service definition it had not understood
//! and produce a service with an operation missing.
//!
//! §7.3.2's grammar also requires an interface to declare at least one
//! method and a class at least one data member — "Note, Java allows
//! empty (marker) interfaces" — which is why an empty body is refused
//! and not merely empty.
//!
//! ## §7.3.2.2, the pair of types
//!
//! A definition may instead be a pair of classes marked
//! `@RPCRequestType` and `@RPCReplyType`. In the Basic Service Mapping
//! each shall carry a member named `header`;
//! [`request_reply_pair`] finds the pair and
//! [`JavaClass::has_header_member`] answers for the member.

extern crate alloc;

use alloc::format;
use alloc::string::{String, ToString};
use alloc::vec::Vec;

use crate::error::{RpcError, RpcResult};
use crate::service_mapping::ParamDirection;
use crate::topic_naming::{DEFAULT_SERVICE_NAME, TopicNameOverrides, validate_service_name};
use crate::type_pair::{PairMapping, ReplyHeaderType, TypePairOptions};

/// The member a request or reply class carries in the Basic Service
/// Mapping. §7.3.2.2.
pub const HEADER_MEMBER: &str = "header";

/// The type of the `header` member of a request class. §7.3.2.2.
pub const REQUEST_HEADER_TYPE: &str = "dds.rpc.RequestHeader";

/// The type of the `header` member of a reply class, where it is
/// `ReplyHeader` (§7.5.1.1.1; see [`ReplyHeaderType`]).
pub const REPLY_HEADER_TYPE: &str = "dds.rpc.ReplyHeader";

/// How deeply a nested declaration is followed before the source is
/// taken to be malformed. §7.3.2's `InterfaceMemberDecl` admits a nested
/// interface or class; nothing sane nests this far.
const MAX_NESTING: usize = 32;

/// One annotation, with whatever named arguments it carried.
///
/// `@DDSService`, `@oneway`, `@in`, `@out`, `@inout`,
/// `@RPCRequestType`, `@RPCReplyType`, `@DDSRequestTopic(name = "…")`
/// and `@DDSReplyTopic(name = "…")` are the ones this specification
/// gives meaning; any other is carried and not interpreted, because an
/// unknown annotation on a Java declaration is a fact about the source
/// and not an error in it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct JavaAnnotation {
    /// The name, without the `@`.
    pub name: String,
    /// `(name = "value")` pairs, in written order. A single unnamed
    /// argument is carried under the name `value`, which is Java's own
    /// rule for the shorthand.
    pub args: Vec<(String, String)>,
}

impl JavaAnnotation {
    /// The value of one named argument.
    #[must_use]
    pub fn arg(&self, name: &str) -> Option<&str> {
        self.args
            .iter()
            .find(|(key, _)| key == name)
            .map(|(_, value)| value.as_str())
    }
}

/// One parameter of a method. §7.3.2.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct JavaParam {
    /// The parameter's name.
    pub name: String,
    /// The direction the annotations gave it; `in` where none did.
    pub direction: ParamDirection,
    /// The type, as the source names it.
    pub type_name: String,
}

/// One method of a service interface. §7.3.2.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct JavaMethod {
    /// The method's name.
    pub name: String,
    /// The return type, absent for `void`.
    pub return_type: Option<String>,
    /// Parameters in declaration order.
    pub params: Vec<JavaParam>,
    /// The `throws` clause, in declaration order.
    pub throws: Vec<String>,
    /// Whether `@oneway` was written on it.
    pub oneway: bool,
    /// Every annotation the source put on it.
    pub annotations: Vec<JavaAnnotation>,
}

/// One data member of a request or reply class. §7.3.2.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct JavaField {
    /// The member's name.
    pub name: String,
    /// The type, as the source names it.
    pub type_name: String,
}

/// A `class`, as `NormalClassDeclaration` admits it. §7.3.2.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct JavaClass {
    /// The class's name.
    pub name: String,
    /// `extends`, where written.
    pub extends: Option<String>,
    /// `implements`, in declaration order.
    pub implements: Vec<String>,
    /// Data members in declaration order.
    pub fields: Vec<JavaField>,
    /// Every annotation the source put on it.
    pub annotations: Vec<JavaAnnotation>,
}

impl JavaClass {
    /// Whether the class carries the `header` member the Basic Service
    /// Mapping requires of a `@RPCRequestType` or `@RPCReplyType`.
    /// §7.3.2.2.
    #[must_use]
    pub fn has_header_member(&self) -> bool {
        self.header_type().is_some()
    }

    /// The type of the `header` member, as the source names it.
    #[must_use]
    pub fn header_type(&self) -> Option<&str> {
        self.fields
            .iter()
            .find(|field| field.name == HEADER_MEMBER)
            .map(|field| field.type_name.as_str())
    }

    /// Whether the source annotated this class with `name`.
    #[must_use]
    pub fn has_annotation(&self, name: &str) -> bool {
        self.annotations
            .iter()
            .any(|annotation| annotation.name == name)
    }
}

/// An `interface`, as `NormalInterfaceDeclaration` admits it. §7.3.2.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct JavaInterface {
    /// The interface's name.
    pub name: String,
    /// `extends`, in declaration order.
    pub bases: Vec<String>,
    /// Methods in declaration order.
    pub methods: Vec<JavaMethod>,
    /// The fields of the body, in declaration order. A field of a Java
    /// interface is a constant: `InterfaceMethodOrFieldDecl` keeps
    /// `ConstantDeclaratorsRest`, which requires an initialiser.
    pub constants: Vec<JavaField>,
    /// Declarations nested inside the body.
    pub nested: Vec<JavaDecl>,
    /// Every annotation the source put on it.
    pub annotations: Vec<JavaAnnotation>,
}

impl JavaInterface {
    /// Whether the source annotated this interface with `name`.
    #[must_use]
    pub fn has_annotation(&self, name: &str) -> bool {
        self.annotations
            .iter()
            .any(|annotation| annotation.name == name)
    }

    /// The effective `<service_name>` of §7.4.1: `@DDSService(name = "…")`
    /// where the source gave one, `"Service"` otherwise. It is the middle
    /// segment of the topic name, not the interface name — the same
    /// precedence [`crate::service_mapping::lower_service`] applies to the
    /// IDL `@service` annotation.
    ///
    /// # Errors
    /// [`RpcError::InvalidServiceName`] when the name is empty or holds
    /// a character §7.4.1's `<user_def_alpha_num>` does not admit.
    pub fn service_name(&self) -> RpcResult<String> {
        let name = self
            .annotations
            .iter()
            .find(|annotation| annotation.name == "DDSService")
            .and_then(|annotation| annotation.arg("name"))
            .map_or_else(|| DEFAULT_SERVICE_NAME.to_string(), ToString::to_string);
        validate_service_name(&name)?;
        Ok(name)
    }

    /// The service this interface defines, with its types still as the
    /// source names them.
    ///
    /// # Errors
    /// [`RpcError::InvalidServiceName`] for a name §7.4.1 does not
    /// admit; [`RpcError::InvalidMethodName`] for an empty method name;
    /// [`RpcError::OnewayWithReturn`] and
    /// [`RpcError::OnewayWithOutParam`] for an inconsistent `@oneway`;
    /// [`RpcError::DuplicateMethod`] and [`RpcError::DuplicateParam`]
    /// for a name declared twice. The same checks
    /// [`crate::service_mapping::lower_service`] runs over an IDL
    /// interface, because the two produce the same service.
    pub fn service_def(&self) -> RpcResult<JavaServiceDef> {
        let service_name = self.service_name()?;
        for (index, method) in self.methods.iter().enumerate() {
            if method.name.is_empty() {
                return Err(RpcError::InvalidMethodName(method.name.clone()));
            }
            if method.oneway {
                if method.return_type.is_some() {
                    return Err(RpcError::OnewayWithReturn(method.name.clone()));
                }
                if let Some(param) = method.params.iter().find(|param| param.direction.is_out()) {
                    return Err(RpcError::OnewayWithOutParam {
                        method: method.name.clone(),
                        param: param.name.clone(),
                    });
                }
            }
            for other in self.methods.iter().skip(index + 1) {
                if other.name == method.name {
                    return Err(RpcError::DuplicateMethod(method.name.clone()));
                }
            }
            for (at, param) in method.params.iter().enumerate() {
                for other in method.params.iter().skip(at + 1) {
                    if other.name == param.name {
                        return Err(RpcError::DuplicateParam {
                            method: method.name.clone(),
                            param: param.name.clone(),
                        });
                    }
                }
            }
        }
        Ok(JavaServiceDef {
            name: self.name.clone(),
            service_name,
            methods: self.methods.clone(),
        })
    }
}

/// A service defined in Java, checked. §7.3.2.
///
/// The counterpart of [`crate::service_mapping::ServiceDef`] for a
/// definition that has no model behind it: same name, same methods, same
/// checks, and types that are still names.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct JavaServiceDef {
    /// The interface's own name — §7.4.1's `<interface_name>`.
    pub name: String,
    /// §7.4.1's `<service_name>`, from `@DDSService(name = "…")` or the
    /// `"Service"` default.
    pub service_name: String,
    /// The methods, in declaration order.
    pub methods: Vec<JavaMethod>,
}

impl JavaServiceDef {
    /// The request and reply topic names, per §7.4.1: the interface name
    /// supplies the first segment, the service name the middle one.
    ///
    /// # Errors
    /// [`RpcError::InvalidServiceName`], which
    /// [`JavaInterface::service_def`] has already ruled out.
    pub fn topic_names(&self) -> RpcResult<crate::topic_naming::ServiceTopicNames> {
        crate::topic_naming::ServiceTopicNames::synthesize(
            crate::topic_naming::BindingStyle::FunctionCall,
            &self.name,
            &[],
            &self.service_name,
            None,
            None,
            &TopicNameOverrides::none(),
        )
    }
}

/// One top-level declaration. §7.3.2's `InterfaceDeclaration` and
/// `ClassDeclaration`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum JavaDecl {
    /// An `interface`.
    Interface(JavaInterface),
    /// A `class`.
    Class(JavaClass),
}

/// The pair of classes §7.3.2.2 defines a service by, checked.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct JavaTypePair<'a> {
    /// The class marked `@RPCRequestType`.
    pub request: &'a JavaClass,
    /// The class marked `@RPCReplyType`; the same declaration as
    /// [`Self::request`] where one class carries both annotations.
    pub reply: &'a JavaClass,
    /// The mapping the pair is written for: [`PairMapping::Basic`] when
    /// both classes carry a `header` member, [`PairMapping::Enhanced`]
    /// when neither does — the decision `crate::type_pair` makes for a
    /// pair written in IDL.
    pub mapping: PairMapping,
}

/// The `@RPCRequestType` / `@RPCReplyType` pair of §7.3.2.2, if the
/// source declares one.
///
/// "A service definition may simply include a pair of types, which may
/// be the same. The request and reply types shall be marked as such
/// using the `@RPCRequestType` and `@RPCReplyType` annotations. Only
/// class types shall be marked as request/reply types." The two may be
/// one class, which is why the pair holds two references that may point
/// at the same declaration rather than two distinct ones.
///
/// "In the Basic Service Mapping, the types annotated as
/// `@RPCRequestType` shall have a member named `header` of type
/// `dds.rpc.RequestHeader` and the types annotated as `@RPCReplyType`
/// shall have a member named `header`" — the reply's type is
/// `dds.rpc.ReplyHeader` unless `options` asks for the literal reading
/// (see [`ReplyHeaderType`]). "When using the Enhanced Service Mapping,
/// the annotations are not necessary and the special data members must
/// not be defined": a pair with neither `header` is Enhanced. The type of
/// `header` is compared as the source writes it, qualified; the reader
/// keeps no import, so a bare `RequestHeader` is not the name this
/// compares.
///
/// `Ok(None)` when no class is marked.
///
/// # Errors
/// [`RpcError::InvalidTypePair`] for a marked interface, more than one
/// request class or more than one reply class, one half without the
/// other, a pair of which only one class has a `header` member, or a
/// `header` of the wrong type.
pub fn request_reply_pair<'a>(
    decls: &'a [JavaDecl],
    options: &TypePairOptions,
) -> RpcResult<Option<JavaTypePair<'a>>> {
    let invalid = |reason: String| RpcError::InvalidTypePair {
        module: String::new(),
        reason,
    };
    let mut requests: Vec<&JavaClass> = Vec::new();
    let mut replies: Vec<&JavaClass> = Vec::new();
    for decl in decls {
        match decl {
            JavaDecl::Class(class) => {
                if class.has_annotation("RPCRequestType") {
                    requests.push(class);
                }
                if class.has_annotation("RPCReplyType") {
                    replies.push(class);
                }
            }
            JavaDecl::Interface(interface) => {
                if interface.has_annotation("RPCRequestType")
                    || interface.has_annotation("RPCReplyType")
                {
                    return Err(invalid(format!(
                        "{} is an interface; only class types are request/reply types",
                        interface.name
                    )));
                }
            }
        }
    }
    if requests.is_empty() && replies.is_empty() {
        return Ok(None);
    }
    let [request] = requests.as_slice() else {
        return Err(invalid(format!(
            "{} classes are marked @RPCRequestType; a pair has one",
            requests.len()
        )));
    };
    let [reply] = replies.as_slice() else {
        return Err(invalid(format!(
            "{} classes are marked @RPCReplyType; a pair has one",
            replies.len()
        )));
    };
    let mapping = match (request.header_type(), reply.header_type()) {
        (Some(request_type), Some(reply_type)) => {
            if request_type != REQUEST_HEADER_TYPE {
                return Err(invalid(format!(
                    "the header of {} is {request_type}, not {REQUEST_HEADER_TYPE}",
                    request.name
                )));
            }
            let wanted = match options.reply_header {
                ReplyHeaderType::ReplyHeader => REPLY_HEADER_TYPE,
                ReplyHeaderType::RequestHeader => REQUEST_HEADER_TYPE,
            };
            if reply_type != wanted {
                return Err(invalid(format!(
                    "the header of {} is {reply_type}, not {wanted}",
                    reply.name
                )));
            }
            PairMapping::Basic
        }
        (None, None) => PairMapping::Enhanced,
        _ => {
            return Err(invalid(
                "only one of the two classes has a `header` member; the Basic Service Mapping \
                 needs it in both and the Enhanced Service Mapping in neither"
                    .to_string(),
            ));
        }
    };
    Ok(Some(JavaTypePair {
        request,
        reply,
        mapping,
    }))
}

/// Read a service definition written in Java. §7.3.2.
///
/// # Errors
/// [`RpcError::JavaSyntax`], naming what the grammar expected, what
/// stood there and the line — for a construct the modified productions
/// removed as much as for one Java never had.
pub fn parse(source: &str) -> RpcResult<Vec<JavaDecl>> {
    let tokens = tokenise(source)?;
    let mut cursor = Cursor { tokens, at: 0 };
    let mut out = Vec::new();
    while cursor.peek().is_some() {
        // A package or import line has nothing to do with the service
        // definition and is skipped whole rather than refused: §7.3.2
        // quotes the declaration productions and a Java file that
        // carries them carries a package line too.
        if cursor.eat_keyword("package") || cursor.eat_keyword("import") {
            cursor.skip_to_semicolon();
            continue;
        }
        out.push(cursor.declaration(0)?);
    }
    Ok(out)
}

// -- the reader --------------------------------------------------------

#[derive(Debug, Clone, PartialEq, Eq)]
struct Token {
    text: String,
    kind: Kind,
    line: usize,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Kind {
    /// An identifier or a keyword.
    Word,
    /// A single punctuation character.
    Punct,
    /// A `"…"` literal, with the quotes removed.
    Str,
}

/// Every modifier `{Modifier}` admits before a `MemberDecl`.
const MODIFIERS: &[&str] = &[
    "public",
    "protected",
    "private",
    "static",
    "final",
    "abstract",
    "native",
    "synchronized",
    "transient",
    "volatile",
    "strictfp",
    "default",
];

fn tokenise(source: &str) -> RpcResult<Vec<Token>> {
    let mut out = Vec::new();
    let bytes: Vec<char> = source.chars().collect();
    let mut at = 0usize;
    let mut line = 1usize;
    while at < bytes.len() {
        let Some(&ch) = bytes.get(at) else { break };
        if ch == '\n' {
            line += 1;
            at += 1;
            continue;
        }
        if ch.is_whitespace() {
            at += 1;
            continue;
        }
        // `//` to end of line, `/* … */` to the closing pair.
        if ch == '/' && bytes.get(at + 1) == Some(&'/') {
            while at < bytes.len() && bytes.get(at) != Some(&'\n') {
                at += 1;
            }
            continue;
        }
        if ch == '/' && bytes.get(at + 1) == Some(&'*') {
            at += 2;
            while at < bytes.len() {
                if bytes.get(at) == Some(&'\n') {
                    line += 1;
                }
                if bytes.get(at) == Some(&'*') && bytes.get(at + 1) == Some(&'/') {
                    at += 2;
                    break;
                }
                at += 1;
            }
            continue;
        }
        if ch == '"' {
            at += 1;
            let mut text = String::new();
            loop {
                let Some(&ch) = bytes.get(at) else {
                    return Err(RpcError::JavaSyntax {
                        expected: "a closing quote",
                        found: text,
                        line,
                    });
                };
                at += 1;
                if ch == '"' {
                    break;
                }
                if ch == '\n' {
                    return Err(RpcError::JavaSyntax {
                        expected: "a closing quote",
                        found: text,
                        line,
                    });
                }
                text.push(ch);
            }
            out.push(Token {
                text,
                kind: Kind::Str,
                line,
            });
            continue;
        }
        if ch.is_alphanumeric() || ch == '_' || ch == '$' {
            let start = at;
            while at < bytes.len()
                && bytes
                    .get(at)
                    .is_some_and(|c| c.is_alphanumeric() || *c == '_' || *c == '$')
            {
                at += 1;
            }
            out.push(Token {
                text: bytes.get(start..at).unwrap_or_default().iter().collect(),
                kind: Kind::Word,
                line,
            });
            continue;
        }
        out.push(Token {
            text: ch.to_string(),
            kind: Kind::Punct,
            line,
        });
        at += 1;
    }
    Ok(out)
}

struct Cursor {
    tokens: Vec<Token>,
    at: usize,
}

impl Cursor {
    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.at)
    }

    fn peek_text(&self) -> &str {
        self.peek().map_or("", |token| token.text.as_str())
    }

    fn line(&self) -> usize {
        self.peek()
            .map_or_else(|| self.tokens.last().map_or(1, |t| t.line), |t| t.line)
    }

    fn found(&self) -> String {
        self.peek()
            .map_or_else(|| "end of source".to_string(), |t| t.text.clone())
    }

    fn error<T>(&self, expected: &'static str) -> RpcResult<T> {
        Err(RpcError::JavaSyntax {
            expected,
            found: self.found(),
            line: self.line(),
        })
    }

    fn eat(&mut self, text: &str) -> bool {
        if self.peek_text() == text {
            self.at += 1;
            return true;
        }
        false
    }

    fn eat_keyword(&mut self, word: &str) -> bool {
        if self
            .peek()
            .is_some_and(|t| t.kind == Kind::Word && t.text == word)
        {
            self.at += 1;
            return true;
        }
        false
    }

    fn expect(&mut self, text: &str, expected: &'static str) -> RpcResult<()> {
        if self.eat(text) {
            return Ok(());
        }
        self.error(expected)
    }

    fn identifier(&mut self, expected: &'static str) -> RpcResult<String> {
        let Some(token) = self.peek() else {
            return self.error(expected);
        };
        if token.kind != Kind::Word {
            return self.error(expected);
        }
        let text = token.text.clone();
        self.at += 1;
        Ok(text)
    }

    fn skip_to_semicolon(&mut self) {
        while self.peek().is_some() && !self.eat(";") {
            self.at += 1;
        }
    }

    /// `{Annotation}` before a declaration or a parameter.
    fn annotations(&mut self) -> RpcResult<Vec<JavaAnnotation>> {
        let mut out = Vec::new();
        while self.eat("@") {
            let name = self.identifier("an annotation name")?;
            let mut args = Vec::new();
            if self.eat("(") {
                // Either `(name = value, …)` or Java's single-argument
                // shorthand `(value)`, which the language names `value`.
                loop {
                    if self.eat(")") {
                        break;
                    }
                    let first = self.value("an annotation argument")?;
                    if self.eat("=") {
                        let value = self.value("an annotation argument's value")?;
                        args.push((first, value));
                    } else {
                        args.push(("value".to_string(), first));
                    }
                    if self.eat(",") {
                        continue;
                    }
                    self.expect(")", "`,` or `)`")?;
                    break;
                }
            }
            out.push(JavaAnnotation { name, args });
        }
        Ok(out)
    }

    /// One annotation argument: an identifier or a string literal.
    fn value(&mut self, expected: &'static str) -> RpcResult<String> {
        let Some(token) = self.peek() else {
            return self.error(expected);
        };
        if token.kind == Kind::Punct {
            return self.error(expected);
        }
        let text = token.text.clone();
        self.at += 1;
        Ok(text)
    }

    /// `{Modifier}`, discarded: none of them changes the service.
    fn modifiers(&mut self) {
        while self
            .peek()
            .is_some_and(|t| t.kind == Kind::Word && MODIFIERS.contains(&t.text.as_str()))
        {
            self.at += 1;
        }
    }

    /// A type: a dotted name with any number of `[]` suffixes.
    ///
    /// No `<…>`: `NormalInterfaceDeclaration` and
    /// `NormalClassDeclaration` both removed generic type parameters,
    /// and a type argument here would be one the grammar does not admit.
    fn type_name(&mut self, expected: &'static str) -> RpcResult<String> {
        let mut name = self.identifier(expected)?;
        while self.peek_text() == "." {
            self.at += 1;
            name.push('.');
            name.push_str(&self.identifier(expected)?);
        }
        if self.peek_text() == "<" {
            return self.error("a type without type arguments — §7.3.2 removed generics");
        }
        while self.eat("[") {
            self.expect("]", "`]`")?;
            name.push_str("[]");
        }
        Ok(name)
    }

    /// zerodds-lint: recursion-depth 32 (nested declarations; bounded by `MAX_NESTING`)
    fn declaration(&mut self, depth: usize) -> RpcResult<JavaDecl> {
        if depth > MAX_NESTING {
            return self.error("a declaration nested less than 32 deep");
        }
        let annotations = self.annotations()?;
        self.modifiers();
        if self.eat_keyword("interface") {
            return Ok(JavaDecl::Interface(self.interface(annotations, depth)?));
        }
        if self.eat_keyword("class") {
            return Ok(JavaDecl::Class(self.class(annotations)?));
        }
        // `@interface` — an annotation type declaration — is what
        // `InterfaceDeclaration` removed, and `enum` is not among the
        // productions at all. Both land here.
        self.error("`interface` or `class`")
    }

    /// zerodds-lint: recursion-depth 32 (nested interfaces; bounded by `MAX_NESTING`)
    fn interface(
        &mut self,
        annotations: Vec<JavaAnnotation>,
        depth: usize,
    ) -> RpcResult<JavaInterface> {
        if depth > MAX_NESTING {
            return self.error("an interface nested less than 32 deep");
        }
        let name = self.identifier("an interface name")?;
        if self.peek_text() == "<" {
            return self.error("an interface without type parameters — §7.3.2 removed generics");
        }
        let mut bases = Vec::new();
        if self.eat_keyword("extends") {
            loop {
                bases.push(self.type_name("a base interface")?);
                if !self.eat(",") {
                    break;
                }
            }
        }
        self.expect("{", "`{` opening the interface body")?;

        let mut methods = Vec::new();
        let mut constants = Vec::new();
        let mut nested = Vec::new();
        loop {
            if self.eat("}") {
                break;
            }
            if self.peek().is_none() {
                return self.error("`}` closing the interface body");
            }
            if self.eat(";") {
                continue;
            }
            let member_annotations = self.annotations()?;
            self.modifiers();
            if self.peek_text() == "interface" || self.peek_text() == "class" {
                // A nested declaration: rewind past the modifiers this
                // arm already ate, which `declaration` would read again.
                let keyword_is_interface = self.eat_keyword("interface");
                if keyword_is_interface {
                    nested.push(JavaDecl::Interface(
                        self.interface(member_annotations, depth + 1)?,
                    ));
                } else {
                    let _ = self.eat_keyword("class");
                    nested.push(JavaDecl::Class(self.class(member_annotations)?));
                }
                continue;
            }
            self.interface_member(member_annotations, &mut methods, &mut constants)?;
        }

        // §7.3.2's `InterfaceBody` requires one declaration at least:
        // "At least one method must be present in an interface. Note,
        // Java allows empty (marker) interfaces."
        if methods.is_empty() && nested.is_empty() {
            return Err(RpcError::EmptyService(name));
        }

        Ok(JavaInterface {
            name,
            bases,
            methods,
            constants,
            nested,
            annotations,
        })
    }

    /// One `InterfaceMemberDecl` that is not a nested declaration:
    /// `void Identifier VoidInterfaceMethodDeclaratorRest`, or
    /// `InterfaceMethodOrFieldDecl` — a `Type Identifier` followed by a
    /// method declarator or by the constant declarators of a field.
    fn interface_member(
        &mut self,
        annotations: Vec<JavaAnnotation>,
        methods: &mut Vec<JavaMethod>,
        constants: &mut Vec<JavaField>,
    ) -> RpcResult<()> {
        if self.eat_keyword("void") {
            let name = self.identifier("a method name")?;
            methods.push(self.method_rest(annotations, None, name)?);
            return Ok(());
        }
        let type_name = self.type_name("a return type, a field type or `void`")?;
        let name = self.identifier("a method name or a field name")?;
        if self.peek_text() == "(" {
            methods.push(self.method_rest(annotations, Some(type_name), name)?);
        } else {
            // `InterfaceMethodOrFieldRest: ConstantDeclaratorsRest ;`
            constants.extend(self.variable_declarators(&type_name, name, true)?);
            self.expect(";", "`;` closing the field declaration")?;
        }
        Ok(())
    }

    /// `VariableDeclaratorRest {, VariableDeclarator}` after the first
    /// declarator's name: `{[]}` and `[= VariableInitializer]` for each
    /// of them. Dimensions after a name add to the dimensions of the
    /// type, as Java reads `int[] a[]`.
    ///
    /// The initialiser is skipped, balanced: it is a value, not part of
    /// the service definition, and may hold commas inside `{…}` or
    /// `(…)`. `require_initialiser` is the constant of an interface,
    /// where `ConstantDeclaratorRest` makes it mandatory.
    fn variable_declarators(
        &mut self,
        type_name: &str,
        first: String,
        require_initialiser: bool,
    ) -> RpcResult<Vec<JavaField>> {
        let mut out = Vec::new();
        let mut name = first;
        loop {
            let mut declared = type_name.to_string();
            while self.eat("[") {
                self.expect("]", "`]`")?;
                declared.push_str("[]");
            }
            if self.eat("=") {
                self.skip_initialiser()?;
            } else if require_initialiser {
                return self.error("`=` — a field of an interface is a constant and needs a value");
            }
            out.push(JavaField {
                name,
                type_name: declared,
            });
            if !self.eat(",") {
                break;
            }
            name = self.identifier("a member name")?;
        }
        Ok(out)
    }

    /// Skips a `VariableInitializer` up to the `,` or `;` that ends the
    /// declarator, keeping count of `(`, `[` and `{` so that a comma
    /// inside an array initialiser or a call does not end it.
    fn skip_initialiser(&mut self) -> RpcResult<()> {
        let mut depth = 0usize;
        loop {
            let Some(token) = self.peek() else {
                return self.error("`;` closing the member declaration");
            };
            if token.kind == Kind::Punct {
                match token.text.as_str() {
                    "(" | "[" | "{" => depth += 1,
                    ")" | "]" | "}" => {
                        if depth == 0 {
                            return self.error("`;` closing the member declaration");
                        }
                        depth -= 1;
                    }
                    "," | ";" if depth == 0 => return Ok(()),
                    _ => {}
                }
            }
            self.at += 1;
        }
    }

    /// The rest of a method declarator, after its name: the parameter
    /// list, the `throws` clause and the closing `;`.
    fn method_rest(
        &mut self,
        annotations: Vec<JavaAnnotation>,
        return_type: Option<String>,
        name: String,
    ) -> RpcResult<JavaMethod> {
        self.expect("(", "`(` opening the parameter list")?;

        let mut params = Vec::new();
        loop {
            if self.eat(")") {
                break;
            }
            let param_annotations = self.annotations()?;
            let _ = self.eat_keyword("final");
            let type_name = self.type_name("a parameter type")?;
            let param_name = self.identifier("a parameter name")?;
            params.push(JavaParam {
                // "By default the parameters are read only, and the use
                // of `@in` is optional."
                direction: direction_of(&param_annotations),
                name: param_name,
                type_name,
            });
            if self.eat(",") {
                continue;
            }
            self.expect(")", "`,` or `)`")?;
            break;
        }

        let mut throws = Vec::new();
        if self.eat_keyword("throws") {
            // The example in §7.3.2.1 writes `throws (TooFast)`, with
            // parentheses Java itself does not use. Both spellings are
            // accepted: the clause is what the specification prints.
            let bracketed = self.eat("(");
            loop {
                throws.push(self.type_name("an exception type")?);
                if !self.eat(",") {
                    break;
                }
            }
            if bracketed {
                self.expect(")", "`)` closing the throws clause")?;
            }
        }

        if self.peek_text() == "{" {
            return self.error("`;` — §7.3.2 admits no method body in an interface");
        }
        self.expect(";", "`;` closing the method declaration")?;

        Ok(JavaMethod {
            oneway: annotations
                .iter()
                .any(|annotation| annotation.name == "oneway"),
            name,
            return_type,
            params,
            throws,
            annotations,
        })
    }

    fn class(&mut self, annotations: Vec<JavaAnnotation>) -> RpcResult<JavaClass> {
        let name = self.identifier("a class name")?;
        if self.peek_text() == "<" {
            return self.error("a class without type parameters — §7.3.2 removed generics");
        }
        let extends = if self.eat_keyword("extends") {
            Some(self.type_name("a base class")?)
        } else {
            None
        };
        let mut implements = Vec::new();
        if self.eat_keyword("implements") {
            loop {
                implements.push(self.type_name("an implemented interface")?);
                if !self.eat(",") {
                    break;
                }
            }
        }
        self.expect("{", "`{` opening the class body")?;

        let mut fields = Vec::new();
        loop {
            if self.eat("}") {
                break;
            }
            if self.peek().is_none() {
                return self.error("`}` closing the class body");
            }
            // `ClassBodyDeclaration: ;` — an empty declaration.
            if self.eat(";") {
                continue;
            }
            let _ = self.annotations()?;
            self.modifiers();
            if self.peek_text() == "{" {
                return self.error("a data member — §7.3.2 removed the static initialiser block");
            }
            let type_name = self.type_name("a member type")?;
            let member = self.identifier("a member name")?;
            if self.peek_text() == "(" {
                return self.error(
                    "a data member — §7.3.2's `MemberDecl` admits no method or constructor in \
                     a class body",
                );
            }
            // `MethodOrFieldRest: VariableDeclaratorRest`, and the further
            // declarators of the same type.
            fields.extend(self.variable_declarators(&type_name, member, false)?);
            self.expect(";", "`;` closing the member declaration")?;
        }

        // §7.3.2's `ClassBody`: "At least one data member must be
        // defined in the class body. Note, Java allows empty classes."
        if fields.is_empty() {
            return Err(RpcError::JavaSyntax {
                expected: "at least one data member",
                found: name,
                line: self.line(),
            });
        }

        Ok(JavaClass {
            name,
            extends,
            implements,
            fields,
            annotations,
        })
    }
}

/// The direction the annotations on a parameter give it. §7.3.2: "By
/// default the parameters are read only, and the use of `@in` is
/// optional."
fn direction_of(annotations: &[JavaAnnotation]) -> ParamDirection {
    for annotation in annotations {
        match annotation.name.as_str() {
            "out" => return ParamDirection::Out,
            "inout" => return ParamDirection::InOut,
            _ => {}
        }
    }
    ParamDirection::In
}

#[cfg(test)]
#[allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]
mod tests {
    use super::*;

    /// §7.3.2.1's example, verbatim from the specification (page 21),
    /// with the `Public` of the printed text lower-cased — Java has no
    /// `Public` keyword and the specification's own example does not
    /// compile as printed.
    const ROBOT_CONTROL: &str = r#"
        public class TooFast extends Exception
        {
            String reason;
        }

        @DDSService
        public interface RobotControl
        {
            void     command(Command com);

            float setSpeed(float speed) throws (TooFast);
            float getSpeed();
            void     getStatus(@out Status status);
        }
    "#;

    #[test]
    fn the_example_of_seven_three_two_one_parses() {
        let decls = parse(ROBOT_CONTROL).expect("the example");
        assert_eq!(decls.len(), 2);
        let JavaDecl::Class(too_fast) = &decls[0] else {
            panic!("the first declaration is a class");
        };
        assert_eq!(too_fast.name, "TooFast");
        assert_eq!(too_fast.extends.as_deref(), Some("Exception"));

        let JavaDecl::Interface(control) = &decls[1] else {
            panic!("the second declaration is an interface");
        };
        assert_eq!(control.name, "RobotControl");
        assert!(control.has_annotation("DDSService"));
        assert_eq!(
            control
                .methods
                .iter()
                .map(|method| method.name.as_str())
                .collect::<Vec<_>>(),
            vec!["command", "setSpeed", "getSpeed", "getStatus"]
        );
    }

    #[test]
    fn a_return_type_and_a_void_are_told_apart() {
        let decls = parse(ROBOT_CONTROL).expect("the example");
        let JavaDecl::Interface(control) = &decls[1] else {
            panic!("an interface");
        };
        assert_eq!(control.methods[0].return_type, None, "`void command(…)`");
        assert_eq!(
            control.methods[1].return_type.as_deref(),
            Some("float"),
            "`float setSpeed(…)`"
        );
        assert_eq!(control.methods[1].throws, vec!["TooFast".to_string()]);
    }

    /// "In, out, and inout parameters are specified using the `@in`,
    /// `@out` and `@inout` annotations. By default the parameters are
    /// read only, and the use of `@in` is optional."
    #[test]
    fn the_direction_annotations_of_seven_three_two_are_read() {
        let decls = parse(
            "interface Ops {
               void f(long implicit, @in long explicit, @out long o, @inout long io);
             }",
        )
        .expect("the interface");
        let JavaDecl::Interface(ops) = &decls[0] else {
            panic!("an interface");
        };
        assert_eq!(
            ops.methods[0]
                .params
                .iter()
                .map(|param| param.direction)
                .collect::<Vec<_>>(),
            vec![
                ParamDirection::In,
                ParamDirection::In,
                ParamDirection::Out,
                ParamDirection::InOut,
            ]
        );
    }

    /// "One or more operations may be marked oneway using the `@oneway`
    /// annotation."
    #[test]
    fn the_oneway_annotation_is_read_and_checked() {
        let decls = parse("interface Ops { @oneway void reset(); }").expect("the interface");
        let JavaDecl::Interface(ops) = &decls[0] else {
            panic!("an interface");
        };
        assert!(ops.methods[0].oneway);
        assert!(ops.service_def().is_ok());

        let decls = parse("interface Ops { @oneway long count(); }").expect("the interface");
        let JavaDecl::Interface(ops) = &decls[0] else {
            panic!("an interface");
        };
        assert_eq!(
            ops.service_def().unwrap_err(),
            RpcError::OnewayWithReturn("count".to_string())
        );

        let decls =
            parse("interface Ops { @oneway void go(@out long r); }").expect("the interface");
        let JavaDecl::Interface(ops) = &decls[0] else {
            panic!("an interface");
        };
        assert_eq!(
            ops.service_def().unwrap_err(),
            RpcError::OnewayWithOutParam {
                method: "go".to_string(),
                param: "r".to_string(),
            }
        );
    }

    /// The service name and its two topics, from a Java definition —
    /// §7.3.2 into §7.4.1.
    #[test]
    fn a_java_definition_reaches_the_topic_names() {
        let decls = parse("@DDSService public interface Calculator { long add(long a, long b); }")
            .expect("the interface");
        let JavaDecl::Interface(calculator) = &decls[0] else {
            panic!("an interface");
        };
        let service = calculator.service_def().expect("the service");
        assert_eq!(service.name, "Calculator");
        let topics = service.topic_names().expect("the topic names");
        assert_eq!(topics.request, "Calculator_Service_Request");
        assert_eq!(topics.reply, "Calculator_Service_Reply");
    }

    /// `@DDSService(name = "…")` supplies §7.4.1's `<service_name>`, the
    /// middle segment of the topic name; `<interface_name>` still comes
    /// from the interface. It does not replace the interface name.
    #[test]
    fn the_service_annotation_overrides_the_interface_name() {
        let decls =
            parse("@DDSService(name = \"Arithmetic\") interface Calculator { long add(long a); }")
                .expect("the interface");
        let JavaDecl::Interface(calculator) = &decls[0] else {
            panic!("an interface");
        };
        assert_eq!(calculator.service_name().unwrap(), "Arithmetic");
        let service = calculator.service_def().expect("the service");
        assert_eq!(service.name, "Calculator");
        assert_eq!(service.service_name, "Arithmetic");
        let topics = service.topic_names().expect("the topic names");
        assert_eq!(topics.request, "Calculator_Arithmetic_Request");
        assert_eq!(topics.reply, "Calculator_Arithmetic_Reply");
    }

    /// §7.3.2.2: a pair of classes marked `@RPCRequestType` and
    /// `@RPCReplyType`, each carrying a `header` member in the Basic
    /// Service Mapping.
    #[test]
    fn the_pair_of_types_of_seven_three_two_two_is_found() {
        let decls = parse(
            "@RPCRequestType class AddRequest { dds.rpc.RequestHeader header; long a; }
             @RPCReplyType   class AddReply   { dds.rpc.ReplyHeader header; long sum; }",
        )
        .expect("the pair");
        let pair = request_reply_pair(&decls, &TypePairOptions::default())
            .expect("a valid pair")
            .expect("a pair");
        assert_eq!(pair.request.name, "AddRequest");
        assert_eq!(pair.reply.name, "AddReply");
        assert_eq!(pair.mapping, PairMapping::Basic);
        assert!(pair.request.has_header_member());
        assert!(pair.reply.has_header_member());
        assert_eq!(pair.request.fields[0].type_name, "dds.rpc.RequestHeader");
        assert_eq!(pair.request.header_type(), Some("dds.rpc.RequestHeader"));
    }

    /// "A service definition may simply include a pair of types, which
    /// may be the same."
    #[test]
    fn one_class_may_be_both_halves_of_the_pair() {
        let decls = parse(
            "@RPCRequestType @RPCReplyType class Echo { dds.rpc.RequestHeader header; long v; }",
        )
        .expect("the class");
        // The one class has one header, of the request type: the reply
        // reading of the class is `RequestHeader` literally.
        let options = TypePairOptions {
            reply_header: ReplyHeaderType::RequestHeader,
            ..TypePairOptions::default()
        };
        let pair = request_reply_pair(&decls, &options)
            .expect("a valid pair")
            .expect("a pair");
        assert_eq!(pair.request.name, pair.reply.name);
        assert_eq!(pair.mapping, PairMapping::Basic);
    }

    /// §7.3.2.2 Enhanced: "the annotations are not necessary and the
    /// special data members must not be defined." A marked pair with no
    /// `header` in either class is an Enhanced pair, as `type_pair.rs`
    /// decides it for IDL.
    #[test]
    fn a_pair_without_headers_is_an_enhanced_pair() {
        let decls =
            parse("@RPCRequestType class Req { long a; } @RPCReplyType class Rep { long r; }")
                .expect("the classes");
        let pair = request_reply_pair(&decls, &TypePairOptions::default())
            .expect("a valid pair")
            .expect("a pair");
        assert_eq!(pair.mapping, PairMapping::Enhanced);
        assert!(!pair.request.has_header_member());
    }

    /// No marked class is no pair, and says so without an error.
    #[test]
    fn no_marked_class_is_no_pair() {
        let decls = parse("class Plain { long v; } interface Ops { long f(); }").expect("source");
        assert!(
            request_reply_pair(&decls, &TypePairOptions::default())
                .expect("no error")
                .is_none()
        );
    }

    fn pair_error(source: &str, options: &TypePairOptions) -> String {
        let decls = parse(source).expect("the source parses");
        match request_reply_pair(&decls, options).unwrap_err() {
            RpcError::InvalidTypePair { reason, .. } => reason,
            other => panic!("{other:?}"),
        }
    }

    /// §7.3.2.2: "Only class types shall be marked as request/reply
    /// types." A marked interface is reported, whichever half it is.
    #[test]
    fn a_marked_interface_is_reported() {
        for source in [
            "@RPCRequestType interface Req { long f(); } @RPCReplyType class Rep { long r; }",
            "@RPCRequestType class Req { long a; } @RPCReplyType interface Rep { long f(); }",
        ] {
            let reason = pair_error(source, &TypePairOptions::default());
            assert!(reason.contains("is an interface"), "{reason}");
            assert!(reason.contains("only class types"), "{reason}");
        }
    }

    /// §7.3.2.2 Basic: the request's `header` is `dds.rpc.RequestHeader`,
    /// the reply's the reply header; the type is checked and not only the
    /// name.
    #[test]
    fn the_type_of_the_header_member_is_checked() {
        let wrong_request = pair_error(
            "@RPCRequestType class Req { dds.rpc.ReplyHeader header; long a; }
             @RPCReplyType class Rep { dds.rpc.ReplyHeader header; long r; }",
            &TypePairOptions::default(),
        );
        assert!(
            wrong_request.contains("not dds.rpc.RequestHeader"),
            "{wrong_request}"
        );
        let wrong_reply = pair_error(
            "@RPCRequestType class Req { dds.rpc.RequestHeader header; long a; }
             @RPCReplyType class Rep { long header; long r; }",
            &TypePairOptions::default(),
        );
        assert!(
            wrong_reply.contains("not dds.rpc.ReplyHeader"),
            "{wrong_reply}"
        );
        // The literal reading of the sentence of §7.3.2.2 takes
        // `RequestHeader` for the reply as well, and then refuses the
        // `ReplyHeader`.
        let literal = TypePairOptions {
            reply_header: ReplyHeaderType::RequestHeader,
            ..TypePairOptions::default()
        };
        let reason = pair_error(
            "@RPCRequestType class Req { dds.rpc.RequestHeader header; long a; }
             @RPCReplyType class Rep { dds.rpc.ReplyHeader header; long r; }",
            &literal,
        );
        assert!(reason.contains("not dds.rpc.RequestHeader"), "{reason}");
    }

    /// A `header` in one class only is neither mapping.
    #[test]
    fn a_header_in_only_one_class_is_reported() {
        let reason = pair_error(
            "@RPCRequestType class Req { dds.rpc.RequestHeader header; long a; }
             @RPCReplyType class Rep { long r; }",
            &TypePairOptions::default(),
        );
        assert!(reason.contains("only one of the two classes"), "{reason}");
    }

    /// One half without the other, and two of a half, are reported as
    /// `type_pair.rs` reports them for IDL.
    #[test]
    fn an_incomplete_or_ambiguous_pair_is_reported() {
        let missing_reply = pair_error(
            "@RPCRequestType class Req { long a; }",
            &TypePairOptions::default(),
        );
        assert!(missing_reply.contains("@RPCReplyType"), "{missing_reply}");
        let two_requests = pair_error(
            "@RPCRequestType class A { long a; } @RPCRequestType class B { long b; }
             @RPCReplyType class R { long r; }",
            &TypePairOptions::default(),
        );
        assert!(two_requests.contains("2 classes"), "{two_requests}");
    }

    /// `InterfaceMethodOrFieldDecl` keeps the field: a constant, whose
    /// declarator needs its value (`ConstantDeclaratorRest`).
    #[test]
    fn a_field_in_an_interface_body_is_a_constant() {
        let decls = parse(
            "interface Ops {
               int LIMIT = 3;
               long f();
               String NAMES[] = { \"a\", \"b\" }, FIRST = \"a\";
             }",
        )
        .expect("the interface");
        let JavaDecl::Interface(ops) = &decls[0] else {
            panic!("an interface");
        };
        assert_eq!(ops.methods.len(), 1);
        assert_eq!(
            ops.constants
                .iter()
                .map(|field| (field.name.as_str(), field.type_name.as_str()))
                .collect::<Vec<_>>(),
            vec![("LIMIT", "int"), ("NAMES", "String[]"), ("FIRST", "String")]
        );
        // Without a value it is not a constant, and a field is all an
        // interface can have besides methods.
        assert!(matches!(
            parse("interface Ops { int LIMIT; long f(); }").unwrap_err(),
            RpcError::JavaSyntax { .. }
        ));
    }

    /// `VariableDeclaratorRest: {[]} [= VariableInitializer]`: dimensions
    /// after the name add to the type, as Java reads `int[] a[]`.
    #[test]
    fn dimensions_after_the_name_belong_to_the_type() {
        let decls = parse("class C { int a[]; int[] b[]; int c[][]; int d; }").expect("the class");
        let JavaDecl::Class(class) = &decls[0] else {
            panic!("a class");
        };
        assert_eq!(
            class
                .fields
                .iter()
                .map(|field| (field.name.as_str(), field.type_name.as_str()))
                .collect::<Vec<_>>(),
            vec![
                ("a", "int[]"),
                ("b", "int[][]"),
                ("c", "int[][]"),
                ("d", "int")
            ]
        );
    }

    /// `int a = 1;` reads the member and skips the value.
    #[test]
    fn an_initialised_member_is_read_without_its_value() {
        let decls =
            parse("class C { int a = 1; String s = \"x;y\"; int[] v = {1, 2, 3}; long n; }")
                .expect("the class");
        let JavaDecl::Class(class) = &decls[0] else {
            panic!("a class");
        };
        assert_eq!(
            class
                .fields
                .iter()
                .map(|field| field.name.as_str())
                .collect::<Vec<_>>(),
            vec!["a", "s", "v", "n"]
        );
    }

    /// `int a, b;` declares two members of the one type, and each may
    /// carry its own dimensions and value.
    #[test]
    fn several_declarators_share_one_type() {
        let decls = parse("class C { int a, b; long x = 1, y[] = {2, 3}, z; }").expect("the class");
        let JavaDecl::Class(class) = &decls[0] else {
            panic!("a class");
        };
        assert_eq!(
            class
                .fields
                .iter()
                .map(|field| (field.name.as_str(), field.type_name.as_str()))
                .collect::<Vec<_>>(),
            vec![
                ("a", "int"),
                ("b", "int"),
                ("x", "long"),
                ("y", "long[]"),
                ("z", "long"),
            ]
        );
    }

    /// `NormalClassDeclaration` keeps `implements TypeList`.
    #[test]
    fn the_implements_list_of_a_class_survives() {
        let decls = parse("class C extends B implements I, java.io.Serializable { long v; }")
            .expect("the class");
        let JavaDecl::Class(class) = &decls[0] else {
            panic!("a class");
        };
        assert_eq!(class.extends.as_deref(), Some("B"));
        assert_eq!(
            class.implements,
            vec!["I".to_string(), "java.io.Serializable".to_string()]
        );
    }

    /// A method in a class body and a method body in an interface stay
    /// refused next to the data members the grammar admits.
    #[test]
    fn a_field_does_not_make_a_method_acceptable_in_a_class() {
        assert!(matches!(
            parse("class C { int a = 1; int f() { } }").unwrap_err(),
            RpcError::JavaSyntax { .. }
        ));
    }

    /// Every production §7.3.2 removed is refused by name.
    #[test]
    fn the_removed_productions_are_refused() {
        for (source, what) in [
            ("interface Box<T> { long f(); }", "generic type parameters"),
            ("class Box<T> { long v; }", "generic class parameters"),
            ("@interface Marker { }", "an annotation type declaration"),
            ("class C { static { } long v; }", "a static initialiser"),
            ("class C { long v; void f(); }", "a method in a class body"),
            ("interface I { long f() { } }", "a method body"),
            ("enum Colour { RED }", "an enum declaration"),
        ] {
            let error = parse(source).unwrap_err();
            assert!(
                matches!(error, RpcError::JavaSyntax { .. }),
                "{what} is refused: {error:?} for {source}"
            );
        }
    }

    /// "At least one method must be present in an interface. Note, Java
    /// allows empty (marker) interfaces."
    #[test]
    fn an_empty_interface_body_is_refused() {
        assert_eq!(
            parse("interface Marker { }").unwrap_err(),
            RpcError::EmptyService("Marker".to_string())
        );
    }

    /// "At least one data member must be defined in the class body.
    /// Note, Java allows empty classes."
    #[test]
    fn an_empty_class_body_is_refused() {
        assert!(matches!(
            parse("class Empty { }").unwrap_err(),
            RpcError::JavaSyntax { .. }
        ));
    }

    #[test]
    fn a_package_and_an_import_line_are_skipped() {
        let decls = parse(
            "package org.example.robot;
             import dds.rpc.RequestHeader;
             interface Ops { long f(); }",
        )
        .expect("the interface");
        assert_eq!(decls.len(), 1);
    }

    #[test]
    fn comments_do_not_reach_the_declarations() {
        let decls = parse(
            "// a line comment
             /* a block
                comment */
             interface Ops { long f(); /* trailing */ }",
        )
        .expect("the interface");
        let JavaDecl::Interface(ops) = &decls[0] else {
            panic!("an interface");
        };
        assert_eq!(ops.methods.len(), 1);
    }

    #[test]
    fn a_duplicate_method_and_a_duplicate_parameter_are_reported() {
        let decls = parse("interface Ops { long f(); long f(long a); }").expect("the interface");
        let JavaDecl::Interface(ops) = &decls[0] else {
            panic!("an interface");
        };
        assert_eq!(
            ops.service_def().unwrap_err(),
            RpcError::DuplicateMethod("f".to_string())
        );

        let decls = parse("interface Ops { long f(long a, long a); }").expect("the interface");
        let JavaDecl::Interface(ops) = &decls[0] else {
            panic!("an interface");
        };
        assert_eq!(
            ops.service_def().unwrap_err(),
            RpcError::DuplicateParam {
                method: "f".to_string(),
                param: "a".to_string(),
            }
        );
    }

    /// `NormalInterfaceDeclaration` keeps `extends TypeList`, and
    /// §7.4.2 maps every interface of the hierarchy to its own pair of
    /// topics — so the bases have to survive the read.
    #[test]
    fn the_extends_list_survives() {
        let decls =
            parse("interface Derived extends Base, Other { long f(); }").expect("the interface");
        let JavaDecl::Interface(derived) = &decls[0] else {
            panic!("an interface");
        };
        assert_eq!(derived.bases, vec!["Base".to_string(), "Other".to_string()]);
    }

    /// `InterfaceMemberDecl` keeps a nested interface and a nested
    /// class declaration.
    #[test]
    fn a_nested_declaration_is_kept() {
        let decls = parse(
            "interface Outer {
               long f();
               class Inner { long v; }
               interface Deeper { long g(); }
             }",
        )
        .expect("the interface");
        let JavaDecl::Interface(outer) = &decls[0] else {
            panic!("an interface");
        };
        assert_eq!(outer.methods.len(), 1);
        assert_eq!(outer.nested.len(), 2);
    }

    /// A name §7.4.1's `<user_def_alpha_num>` does not admit is refused
    /// where the topic name would be built from it.
    #[test]
    fn an_invalid_service_name_is_refused() {
        let decls = parse("@DDSService(name = \"my-service\") interface I { long f(); }")
            .expect("the interface");
        let JavaDecl::Interface(interface) = &decls[0] else {
            panic!("an interface");
        };
        assert!(matches!(
            interface.service_name().unwrap_err(),
            RpcError::InvalidServiceName(_)
        ));
    }

    /// An array type and a dotted type both survive the read.
    #[test]
    fn a_dotted_and_an_array_type_survive() {
        let decls =
            parse("interface Ops { void f(org.example.Pose[] poses); }").expect("the interface");
        let JavaDecl::Interface(ops) = &decls[0] else {
            panic!("an interface");
        };
        assert_eq!(ops.methods[0].params[0].type_name, "org.example.Pose[]");
    }
}
